{
  "investigate": [
    {
      "tool": "logs",
      "service": "invoice-agent",
      "level": "ERROR",
      "contains": "disk quota",
      "why": "Check if invoice-agent is also experiencing disk quota issues, which would indicate a shared storage problem rather than a worker-specific issue."
    },
    {
      "tool": "sql",
      "query": "SELECT service, used_mb, quota_mb FROM storage WHERE service IN ('worker', 'invoice-agent')",
      "why": "Verify the current disk usage and quota for worker and invoice-agent to confirm if disk quota is exhausted."
    }
  ],
  "hypotheses": [
    {
      "service": "worker",
      "kind": "resource_exhaustion",
      "mechanism": "Worker's disk quota is exhausted, causing it to fail when writing invoice files, leading to message retries and dead letters.",
      "supporting": ["E9", "E10", "E3", "E5"],
      "refuting": ["E11"],
      "explains": ["M2_error_burst", "M3_dead_letters"],
      "repair_plan": [
        {"action": "restart_service", "params": {"service": "worker"}}
      ]
    }
  ],
  "summary": "Worker is failing due to disk quota exhaustion, causing invoice processing errors and dead letters."
}
